```csharp
using UnityEngine;

public class GemController : MonoBehaviour
{
    // Arreglo para almacenar los GameObjects "Gem"
    public GameObject[] gems;

    // Variable para almacenar el puntaje actual
    public int score = 0;

    // Variable para almacenar la posición actual de laificación de la gem
    public int pickerViewRow = 0;
    public int pickerViewColumn = 0;

    // Método para inicializar el arreglo de GameObjects "Gem"
    void Start()
    {
        // Inicializar arreglo de GameObjects "Gem"
        gems = new GameObject[12];
        for (int i = 0; i < 12; i++)
        {
            GameObject gem = new GameObject("Gem");
            gem.transform.position = new Vector3(i % 4, (int)i / 4, 0);
            gems[i] = gem;
        }
    }

    // Método para actualizar el estado del juego cada帧 (frame)
    void Update()
    {
        // Comprobar si se ha producido una combinación de gems
        CheckCombinations();
    }

    // Método para spawnear nuevas gems en la escena cuando se necesitan
    public void SpawnGem()
    {
        // Crear un nuevo GameObject "Gem" y asignarlo a una posición aleatoria en el grid
        GameObject newGem = new GameObject("Gem");
        newGem.transform.position = new Vector3(Random.Range(0, 4), Random.Range(0, 3), 0);
        gems[Random.Range(0, gems.Length)] = newGem;
    }

    // Método para revisar si se han producido combinaciones de gems
    void CheckCombinations()
    {
        // Recorrer el grid para buscar combinaciones de gems
        for (int i = 0; i < gems.Length; i++)
        {
            // Comprobar si la gem actual se puede combinar con las gems adyacentes
            Gem g = gems[i].GetComponent<Gem>();
            if (g.CanCombine(i % 4, (int)i / 4))
            {
                // Combinar las gems y aumentar el puntaje
                score += g.GetCombinationPoints();
                // Remove the gem from the grid
                Destroy(g.transform.gameObject);
            }
        }
    }
}
```
