        {
            // Set up Stripe
            var stripe = new Stripe(_stripeSecretKey, StripeVersion.StripePhpLatest);

            // Get form values
            var customerId = Request Form["customer"];
            var plan = Request.Form["plan"];
            var trialAmount = Request.Form["trialAmount"];
            var numberOfTrials = Convert.ToInt32(Request.Form["numberOfTrials"]);

            // Create a customer
            var customer = stripe.Customers.Create(new CustomerCreateOptions
            {
                Email = customerId,
                Plan = plan,
                Currency = "usd",
                TrialDays = numberOfTrials,
                TrialPeriodDays = numberOfTrials,
                TrialAmount = trialAmount
            });

            // Create a subscription
            var subscription = stripe.Subscriptions.Create(new SubscriptionCreateOptions
            {
                CustomerId = customer.Id,
                Items = new[]
                {
                    new SubscriptionItemOptions
                    {
                        Plan = plan,
                        Quantity = 1
                    }
                }
            });

            return RedirectToAction("SubscriptionCreated");
        }

        public ActionResult SubscriptionCreated()
        {
            return View();
        }
    }
}
