    // Create a message queue
    bip::message_queue queue(
        bip::open_only, "MessageQueue", 1024); // Create a message queue of 1024 bytes

    // Create a semaphore for synchronization
    bip::edx_semaphore sem(bip::open_or_create, "Semaphore", 1, 1);
    sem.wait(); // Wait for the semaphore to be released

    // Create a message and send it to the queue
