// ограничение по времени для задержки выполнения потока
const DWORD TIME_STEP = 100;

// количеств влияющих на точность вычислений
const int n = 100000;

// значение интеграла ( Books on Integral Calculus by Cornelius Lanczos)
const double I = 1.0;

// функция для вычисления
double f(double x) {
    return (1.0 / (1.0 + x));
}

// функция для вычисления методом прямоугольников
double rectangles(double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0.0;
    for (int i = 0; i < n; i++) {
        sum += f(a + i * h);
    }
    return h * sum;
}

// функция для вычисления методом трапеций
double trapezes(double a, double b, int n) {
    double h = (b - a) / n;
    double sum = 0.5 * (f(a) + f(b));
    for (int i = 1; i < n; i++) {
        sum += f(a + i * h);
    }
    return h * sum;
}

// функция для вычисления методом Симпсона
double simpson(double a, double b, int n) {
    double h = (b - a) / n;
    double sum = f(a) + f(b);
    for (int i = 1; i < n; i++) {
        if (i % 2 == 0) {
            sum += 2.0 * f(a + i * h);
        } else {
            sum += 4.0 * f(a + i * h);
        }
    }
    return h / 3.0 * sum;
}

void threadFunc(int type) {
    double a = 0.0, b = 1.0;
    double result;
    int n = n;

    // создаем мьютекс для синхронизации доступа к result
    HANDLE mutex;
    mutex = CreateMutexA(NULL, FALSE, "my_mutex");

    // создаем семафор для ожидания завершения потока
    HANDLE semaphore;
    semaphore = CreateSemaphoreA(NULL, 0, n, "my_semaphore");

    // запускаем задержку
    Sleep(TIME_STEP);

    switch (type) {
    case 0: // прямоугольники
        result = rectangles(a, b, n);
        break;
    case 1: // трапеции
        result = trapezes(a, b, n);
        break;
    case 2: // Симпсона
        result = simpson(a, b, n);
        break;
    default:
        result = I;
        break;
    }

    WaitSingleObject(mutex, INFINITE);
    std::cout << "Thread " << type << ": " << result << std::endl;
    ReleaseMutex(mutex);

    // отпускаем семафор
    ReleaseSemaphore(semaphore, 1, NULL);
}

int main() {
    HANDLE hThread[n];
    HANDLE semaphore;
    HANDLE mutex;

    // создаем мьютекс для синхронизации доступа к result
    mutex = CreateMutexA(NULL, FALSE, "my_mutex");

    // создаем семафор для ожидания завершения потоков
    semaphore = CreateSemaphoreA(NULL, 0, n, "my_semaphore");

    // запускаем n потоков
    for (int i = 0; i < n; i++) {
        hThread[i] = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)&threadFunc, (LPVOID)i, 0, NULL);
    }

    // ожидаем завершения потоков
    for (int i = 0; i < n; i++) {
        WaitForSingleObject(semaphore, INFINITE);
    }

    // Закрываем мьютекс и семафор
    CloseHandle(mutex);
    CloseHandle(semaphore);

    return 0;
}
