                // Trata o pacote recebido
                ByteBuffer buffer = packet.getBuffer();
                byte[] bytes = new byte[buffer.remaining()];
                buffer.get(bytes);

                System.out.println("Recebido pacote " + byte2hex(bytes));
            }

            private String byte2hex(byte[] bytes) {
