// Estructura del nodo del árbol binario
struct TreeNode {
    int valor;
    TreeNode* izquierda;
    TreeNode* derecha;
};

// Clase para implementar el árbol binario
class BinaryTree {
private:
    TreeNode* raiz;

public:
    BinaryTree(int valor) {
        raiz = new TreeNode();
        raiz->valor = valor;
        raiz->izquierda = raiz->derecha = nullptr;
    }

    // Función para insertar un nuevo nodo en el árbol
    void insertar(int valor) {
        TreeNode* nuevoNodo = new TreeNode();
        nuevoNodo->valor = valor;
        nuevoNodo->izquierda = nuevoNodo->derecha = nullptr;

        if (raiz == nullptr) {
            raiz = nuevoNodo;
        } else {
            TreeNode* actual = raiz;
            while (true) {
                if (actual->valor < valor) {
                    if (actual->derecha == nullptr) {
                        actual->derecha = nuevoNodo;
                        break;
                    }
                    actual = actual->derecha;
                } else {
                    if (actual->izquierda == nullptr) {
                        actual->izquierda = nuevoNodo;
                        break;
                    }
                    actual = actual->izquierda;
                }
            }
        }
    }

    // Función para buscar un valor en el árbol
    bool buscar(int valor) {
        TreeNode* actual = raiz;
        while (actual != nullptr) {
            if (actual->valor == valor) {
                return true;
            } else if (actual->valor < valor) {
                actual = actual->derecha;
            } else {
                actual = actual->izquierda;
            }
        }
        return false;
    }
};

