```pascal
uses
  PDFlib;

procedure TForm1.RotatePDF(fileIn, fileOut: string);
var
  err: PLErr;
  SFOPdf: TPDF;
begin
  SFOPdf := TPDF.Create(nil);
  try
    SFOPdf.LoadFile(fileIn);
    SFOPdf.Rotate(90); // Rotate the PDF 90 degrees counterclockwise
    SFOPdf.SaveFile(fileOut);
  finally
    SFOPdf.Free;
  end;
end;
